import java.util.Arrays;

public class MergeSort {

    public static <T extends Comparable<T>> T[] mergeSort(T[] arr) {
        if (arr == null || arr.length <= 1) {
            return arr; // Handle empty or single-element arrays
        }

        int mid = arr.length / 2;
        T[] left = Arrays.copyOfRange(arr, 0, mid);
        T[] right = Arrays.copyOfRange(arr, mid, arr.length);

        left = mergeSort(left);
        right = mergeSort(right);

        return merge(left, right);
    }

    private static <T extends Comparable<T>> T[] merge(T[] left, T[] right) {
        T[] merged = (T[]) new Comparable[left.length + right.length];
        int i = 0, j = 0, k = 0;

        while (i < left.length && j < right.length) {
            if (left[i].compareTo(right[j]) <= 0) {
                merged[k++] = left[i++];
            } else {
                merged[k++] = right[j++];
            }
        }

        while (i < left.length) {
            merged[k++] = left[i++];
        }

        while (j < right.length) {
            merged[k++] = right[j++];
        }

        return merged;
    }


    public static void main(String[] args) {
        Integer[] arr = {12, 11, 13, 5, 6, 7};
        Integer[] sortedArr = mergeSort(arr);
        System.out.println("Sorted array: " + Arrays.toString(sortedArr));


        String[] strArr = {"banana", "apple", "orange", "grape"};
        String[] sortedStrArr = mergeSort(strArr);
        System.out.println("Sorted string array: " + Arrays.toString(sortedStrArr));

        //test null and empty
        Integer[] nullArr = null;
        Integer[] emptyArr = {};
        System.out.println("Sorted null array: " + Arrays.toString(mergeSort(nullArr)));
        System.out.println("Sorted empty array: " + Arrays.toString(mergeSort(emptyArr)));

    }
}
