import java.util.Arrays;

class MergeSort {

    public static void mergeSort(int[] arr) {
        if (arr == null || arr.length < 2) {
            return; // Already sorted or empty
        }
        int[] temp = Arrays.copyOf(arr, arr.length); // Create a single temp array
        mergeSortHelper(arr, temp, 0, arr.length - 1);
    }

    private static void mergeSortHelper(int[] arr, int[] temp, int left, int right) {
        if (left < right) {
            int mid = left + (right - left) / 2; // Avoid potential overflow
            mergeSortHelper(arr, temp, left, mid);
            mergeSortHelper(arr, temp, mid + 1, right);
            merge(arr, temp, left, mid, right);
        }
    }

    private static void merge(int[] arr, int[] temp, int left, int mid, int right) {
        System.arraycopy(arr, left, temp, left, right - left + 1); //Efficient copy

        int i = left, j = mid + 1, k = left;
        while (i <= mid && j <= right) {
            if (temp[i] <= temp[j]) {
                arr[k++] = temp[i++];
            } else {
                arr[k++] = temp[j++];
            }
        }

        while (i <= mid) {
            arr[k++] = temp[i++];
        }
        //No need for a while loop for j, as the remaining elements are already in place in arr
    }


    public static void main(String[] args) {
        int[] arr = {12, 11, 13, 5, 6, 7};
        System.out.println("Unsorted array: " + Arrays.toString(arr));
        mergeSort(arr);
        System.out.println("Sorted array: " + Arrays.toString(arr));


        int [] arr2 = {5,4,3,2,1};
        System.out.println("Unsorted array: " + Arrays.toString(arr2));
        mergeSort(arr2);
        System.out.println("Sorted array: " + Arrays.toString(arr2));

        int [] arr3 = {};
        System.out.println("Unsorted array: " + Arrays.toString(arr3));
        mergeSort(arr3);
        System.out.println("Sorted array: " + Arrays.toString(arr3));

        int [] arr4 = {1};
        System.out.println("Unsorted array: " + Arrays.toString(arr4));
        mergeSort(arr4);
        System.out.println("Sorted array: " + Arrays.toString(arr4));

        int [] arr5 = {1,1,1,1,1};
        System.out.println("Unsorted array: " + Arrays.toString(arr5));
        mergeSort(arr5);
        System.out.println("Sorted array: " + Arrays.toString(arr5));


    }
}
